<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import StateCard from'../../Components/StateCard.vue';import UiBadge from'../../Components/UiBadge.vue';import UiButton from'../../Components/UiButton.vue';import{Head,router}from'@inertiajs/vue3';import{onBeforeUnmount,onMounted,ref}from'vue';const p=defineProps({event:Object,batches:Array,exports:Array,indexRun:Object});const timer=ref(),busy=ref(null),tone=s=>s==='completed'?'success':s==='failed'?'error':['queued','processing','pending','partially_completed'].includes(s)?'warning':'info';function action(url){busy.value=url;router.post(url,{}, {preserveScroll:true,onFinish:()=>busy.value=null})}onMounted(()=>timer.value=setInterval(()=>router.reload({only:['batches','exports','indexRun'],preserveScroll:true}),3000));onBeforeUnmount(()=>clearInterval(timer.value));</script><template><AppShell><Head title="Processing & exports"/><div class="lp-page"><PageHeader eyebrow="Durable operations" :title="`Processing · ${event.name}`" description="Upload, indexing and export states refresh automatically from queue-backed records."><UiButton variant="secondary" :href="`/groups/${event.id}`">Event workspace</UiButton></PageHeader><div class="mt-8 grid gap-6 xl:grid-cols-2"><section><h2 class="text-xl font-bold">Upload batches</h2><StateCard v-if="!batches.length" class="mt-4" title="No upload batches" message="New uploads will appear here with per-file progress."/><div v-else class="mt-4 space-y-3"><UiCard v-for="batch in batches" :key="batch.uuid"><div class="flex justify-between gap-3"><div><p class="font-semibold">{{batch.total_files}} files</p><p class="text-xs text-slate-500">{{batch.completed_files}} complete · {{batch.failed_files}} failed · {{batch.pending_files}} pending</p></div><UiBadge :tone="tone(batch.state)">{{batch.state}}</UiBadge></div><ul v-if="batch.files?.length" class="mt-4 divide-y divide-slate-100 text-xs"><li v-for="file in batch.files" :key="file.id" class="flex justify-between gap-3 py-2"><span class="truncate">{{file.client_filename}}</span><span :class="file.state==='failed'?'text-red-600':'text-slate-500'">{{file.state}}{{file.error?` · ${file.error}`:''}}</span></li></ul><div class="mt-4 flex gap-2"><UiButton v-if="['pending','queued','processing','partially_completed'].includes(batch.state)" variant="danger" size="sm" :loading="busy===`/processing/batches/${batch.uuid}/cancel`" @click="action(`/processing/batches/${batch.uuid}/cancel`)">Cancel</UiButton><UiButton v-if="batch.failed_files&&!batch.cancelled_at" variant="secondary" size="sm" :loading="busy===`/processing/batches/${batch.uuid}/retry`" @click="action(`/processing/batches/${batch.uuid}/retry`)">Retry failed</UiButton></div></UiCard></div></section><section><h2 class="text-xl font-bold">Exports</h2><StateCard v-if="!exports.length" class="mt-4" title="No exports" message="Select authorized photographs in the event gallery to create an export."/><div v-else class="mt-4 space-y-3"><UiCard v-for="item in exports" :key="item.uuid"><div class="flex justify-between gap-3"><p class="font-semibold">{{item.photo_ids.length}} photos</p><UiBadge :tone="tone(item.state)">{{item.state}}</UiBadge></div><div class="mt-4 flex gap-2"><UiButton v-if="item.state==='completed'" :href="`/exports/${item.uuid}/download`">Download ZIP</UiButton><UiButton v-if="['queued','processing'].includes(item.state)" variant="danger" size="sm" :loading="busy===`/exports/${item.uuid}/cancel`" @click="action(`/exports/${item.uuid}/cancel`)">Cancel export</UiButton></div><p v-if="item.error" class="lp-error">{{item.error}}</p></UiCard></div></section></div><UiCard class="mt-6"><div class="flex flex-wrap justify-between gap-4"><div><h2 class="text-lg font-bold">Face indexing</h2><p class="text-sm text-slate-500">{{indexRun?.completed||0}} / {{indexRun?.total||0}} processed</p></div><div class="flex items-center gap-3"><UiBadge :tone="tone(indexRun?.state||'not_started')">{{indexRun?.state||'not started'}}</UiBadge><UiButton v-if="!indexRun||['failed','completed','cancelled'].includes(indexRun.state)" size="sm" :loading="busy===`/groups/${event.id}/face-index-runs`" @click="action(`/groups/${event.id}/face-index-runs`)">{{indexRun?.state==='failed'?'Resume indexing':'Start indexing'}}</UiButton></div></div></UiCard></div></AppShell></template>
